import type { Guide } from "@/lib/content";

type GuideInput = Omit<Guide, "description" | "reviewedOn"> & { description: string; expansions: string[] };

function makeGuide(input: GuideInput): Guide {
  const { expansions, ...guide } = input;

  return {
    ...guide,
    description: `${input.description} This guide is educational and does not replace medical, legal, or financial advice from a qualified professional.`,
    reviewedOn: "2026-10-17",
    sections: input.sections.map((section, index) => ({
      ...section,
      body: `${section.body.replace(/\.$/, "")}; ${expansions[index]}.`,
    })),
  };
}

